from itertools import permutations
from math import factorial

def _lis_len(p):
    import bisect
    tails = []
    for x in p:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def count_special_permutations(A: int, B: int, M: int) -> int:
    n = A * B - 1
    # Brute force over all permutations of 1..n (only feasible for small n).
    count = 0
    for p in permutations(range(1, n + 1)):
        if _lis_len(p) != A:
            continue
        if _lis_len([-x for x in p]) != B:
            continue
        # Condition 3: exists n' such that appending n'+0.5 changes neither LIS nor LDS.
        # Appending a value v to P: LIS can only stay the same if v cannot extend any
        # increasing subsequence beyond A, and LDS likewise. We test all half-integer
        # positions v = k + 0.5 for k in 0..n.
        ok = False
        for k in range(0, n + 1):
            v = k + 0.5
            q = list(p) + [v]
            if _lis_len(q) == A and _lis_len([-x for x in q]) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

